static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    // Shapes:
    // x: [M, K]
    // weight: [N, K] (PyTorch Linear weight is [out_features, in_features])
    // bias_linear: [N]
    auto x_shape = context->GetInputShape(0)->GetOriginShape();
    auto w_shape = context->GetInputShape(1)->GetOriginShape();

    if (x_shape.GetDimNum() != 2 || w_shape.GetDimNum() != 2) {
        return ge::GRAPH_FAILED;
    }

    uint32_t M = static_cast<uint32_t>(x_shape.GetDim(0));
    uint32_t K = static_cast<uint32_t>(x_shape.GetDim(1));
    uint32_t N = static_cast<uint32_t>(w_shape.GetDim(0)); // weight: [N, K]

    // Build Matmul tiling (single-core for simplicity, kernel will post-process full output)
    auto ascendcPlatform = platform_ascendc::PlatformAscendC(context->GetPlatformInfo());
    matmul_tiling::MatmulApiTiling mmTiling(ascendcPlatform);
    mmTiling.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND,
                      matmul_tiling::DataType::DT_FLOAT16);
    mmTiling.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND,
                      matmul_tiling::DataType::DT_FLOAT16);
    mmTiling.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND,
                      matmul_tiling::DataType::DT_FLOAT);
    mmTiling.SetBiasType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND,
                         matmul_tiling::DataType::DT_FLOAT);
    mmTiling.SetShape(M, N, K);
    mmTiling.SetOrgShape(M, N, K);
    mmTiling.SetBias(true);
    mmTiling.SetBufferSpace(-1, -1, -1);

    optiling::TCubeTiling tilingData;
    int ret = mmTiling.GetTiling(tilingData);
    if (ret != 0) {
        return ge::GRAPH_FAILED;
    }

    // Set single core (post-processing assumes full range processed in one core)
    context->SetBlockDim(1);

    // Write TCubeTiling to raw tiling buffer
    auto raw = context->GetRawTilingData();
    uint8_t* buf = reinterpret_cast<uint8_t*>(raw->GetData());
    uint32_t cap = raw->GetCapacity();
    uint32_t off = 0;

    if (cap < sizeof(optiling::TCubeTiling)) {
        return ge::GRAPH_FAILED;
    }
    // Save TCubeTiling
    ::memcpy(buf, &tilingData, sizeof(optiling::TCubeTiling));
    off += sizeof(optiling::TCubeTiling);

    // Append our extra tiling info
    optiling::MatmulBatchNormBiasAddDivideSwishCustomExtra extra;
    extra.set_M(M);
    extra.set_N(N);
    extra.set_K(K);
    // A reasonable per-feature tile for post-processing, can be tuned
    extra.set_tileN(1024);

    if (cap < off + extra.GetDataSize()) {
        return ge::GRAPH_FAILED;
    }
    extra.SaveToBuffer(buf + off, extra.GetDataSize());
    off += extra.GetDataSize();

    raw->SetDataSize(off);

    // workspace (none)
    size_t* ws = context->GetWorkspaceSizes(1);
    ws[0] = 0;

    return ge::GRAPH_SUCCESS;
}

